"""Test unbounded root-source completeness by an exact mod-two Hilbert series.

An incomplete result records the precise first missing degree; it is not
promoted to a source theorem. The degree-32 orbit norm is an independently
constructed integral invariant, not a guessed saturation generator.
"""
from pathlib import Path
from hashlib import sha256
from time import perf_counter
import argparse,gzip,json
from sage.all import GF,PolynomialRing,TermOrder,prod
ROOT=Path(__file__).resolve().parents[1]

def parse(text,P):
 names={name:i for i,name in enumerate(P.variable_names())};out={};n=P.ngens()
 for term in text.replace(' ','').replace('-','+-').split('+'):
  if not term:continue
  c=-1 if term.startswith('-') else 1;e=[0]*n
  for factor in term.lstrip('-').split('*'):
   name,_,power=factor.partition('^')
   if name in names:e[names[name]]+=int(power) if power else 1
   else:c*=int(factor)
  if c%2:out[tuple(e)]=out.get(tuple(e),0)^1
 return P(out)

def main():
 ap=argparse.ArgumentParser();ap.add_argument('--force-elimination',action='store_true');args=ap.parse_args();start=perf_counter();srcpath=ROOT/'experiments/e7-d5a1-sources.json';data=json.loads(srcpath.read_text());normpath=ROOT/'experiments/e7-d5a1-norm.json';norm=json.loads(normpath.read_text());archive=ROOT/norm['certificate_archive'];assert sha256(archive.read_bytes()).hexdigest()==norm['certificate_archive_sha256'];normdata=json.loads(gzip.decompress(archive.read_bytes()))
 # The independently checked degree-21 indecomposable already disproves
 # this degree-20 list's completeness. A degree-32 norm cannot repair a
 # missing degree-21 component. Avoid an unnecessary unbounded elimination.
 auditpath=ROOT/'experiments/e7-d5a1-sources-22-audit.json'
 if auditpath.exists() and not args.force_elimination:
  audit=json.loads(auditpath.read_text());assert audit['result']=='passed';missing=next(r['degree'] for r in audit['indecomposable_checks'] if r['degree']>data['max_degree'] and r['necessary_new_generators'])
  report=dict(result='incomplete',full_source_complete_all_degrees=False,first_missing_degree=missing,generator_degrees=data['generator_degrees']+[32],reason='The complete degree-21 source has one dimension not generated by all lower-degree source generators, independently checked modulo two. The degree-32 norm cannot contribute in degree 21.',seconds=round(perf_counter()-start,3),source_sha256={p.relative_to(ROOT).as_posix():sha256(p.read_bytes().replace(b'\r\n',b'\n')).hexdigest() for p in (Path(__file__).resolve(),srcpath,normpath,auditpath)});(ROOT/'experiments/e7-d5a1-source-algebra.json').write_text(json.dumps(report,indent=2)+'\n');print(report,flush=True);return
 P=PolynomialRing(GF(2),names=('h','z','c2','c3','c4','c5','r'));gs=[(parse(f,P),d) for f,d in data['generators']]+[(parse(normdata['norm_mod2'],P),32)];ds=[d for f,d in gs];assert gs[0][0]==P.gen(0)
 names=('z','c2','c3','c4','c5','r')+tuple('b'+str(i) for i in range(len(gs)));S=PolynomialRing(GF(2),len(names),names=names,order=TermOrder('wdegrevlex',(1,2,3,4,5,2))+TermOrder('wdegrevlex',ds));vv=S.gens()[6:];phi=P.hom([vv[0]]+list(S.gens()[:6]),S);I=S.ideal([vv[i]-phi(f) for i,(f,d) in enumerate(gs) if i]);print('graph elimination start',len(gs),'generators',flush=True)
 G=I.groebner_basis(algorithm='singular:slimgb');out=[f for f in G if not any(any(e[:6]) for e in f.exponents())];print('GB',len(G),'kernel',len(out),'seconds',round(perf_counter()-start,2),flush=True)
 T=PolynomialRing(GF(2),len(gs),names=names[6:],order=TermOrder('wdegrevlex',ds));rho=S.hom([T.zero()]*6+list(T.gens()),T);J=T.ideal([rho(f) for f in out]);H=J.hilbert_series(grading=ds);q=H.parent().gen();target=1/prod(1-q**d for d in (1,2,2,4,5,6,8));complete=H==target;missing=None
 if not complete:
  series=(target-H).power_series(80);missing=next((d for d in range(80) if series[d]),None)
 cert=dict(elimination_variables=list(names),elimination_grading=[1,2,3,4,5,2]+ds,elimination_relations=list(map(str,I.gens())),elimination_groebner=list(map(str,G)),kernel=[str(rho(f)) for f in out]);resultarchive=ROOT/'experiments/e7-d5a1-source-algebra-certificates.json.gz';resultarchive.write_bytes(gzip.compress(json.dumps(cert,separators=(',',':')).encode(),mtime=0))
 report=dict(result='passed' if complete else 'incomplete',full_source_complete_all_degrees=complete,first_missing_degree=missing,generator_degrees=ds,hilbert_series=str(H),target_hilbert_series=str(target),seconds=round(perf_counter()-start,3),certificate_archive=resultarchive.relative_to(ROOT).as_posix(),certificate_archive_sha256=sha256(resultarchive.read_bytes()).hexdigest(),source_sha256={p.relative_to(ROOT).as_posix():sha256(p.read_bytes().replace(b'\r\n',b'\n')).hexdigest() for p in (Path(__file__).resolve(),srcpath,normpath)});(ROOT/'experiments/e7-d5a1-source-algebra.json').write_text(json.dumps(report,indent=2)+'\n');print(report,flush=True)

if __name__=='__main__':main()
